		s = s[:j]
	}
	return pyStrip(s)
}

func cutLyricHeader(s string) string {
	if !strings.HasPrefix(s, "#") {
		return s
	}
	rest := strings.TrimLeftFunc(s[1:], isPySpace)
	if len(rest) < 4 || !strings.EqualFold(rest[:4], "lyri") {
		return s
	}
