	tail := func(t string) (string, bool) {
		n := len(t) - len(strings.TrimLeftFunc(t, isPySpace))
		if k := strings.LastIndexByte(t[:n], '\n'); k >= 0 {
			return t[k+1:], true
		}
		return "", false
	}
	if rest != "" && strings.ContainsRune("cCsS|", rune(rest[0])) {
		if t, ok := tail(rest[1:]); ok {
			return t
		}
	}
	if t, ok := tail(rest); ok {
		return t
	}
	return s
}

