		if err != nil {
			return "", st, err
		}
		scores := out[0]
		f.Apply(scores)
		topP(scores, p.S.TopP)
		tok := int32(draw(scores, p.S.Temperature, rng))
		f.Update(tok)
		gen = append(gen, tok)
		if tok == ImEndID || tok == EndOfTextID {
			break
		}
		if err := p.after(phase, len(gen), 0); err != nil {
			return "", st, err
		}
		step[0].ID = tok
		step[0].Pos++
	}
	st.Steps, st.Tokens = time.Since(t0), len(gen)
	text, err := p.Tk.Decode(gen)
	return text, st, err
}

